export type VectorFont = OpentypeFont;
export type BuiltinFont = 'roboto' | 'excalifont' | 'virgil' | 'Fredericka the Great' | 'fredericka the great' | 'fredericka' | 'firacode' | 'Fira Code';
export type FontStyle = BuiltinFont | (string & {});
export type FontSource = string | ArrayBuffer | Uint8Array | Blob;
export interface MSDFOptions {
    fontSize?: number;
